/** Small deterministic presentation clock. It never grants rewards or mutates the simulation. */
export function createPerformance(beats){return {beats:structuredClone(beats||[]),index:0,elapsed:0,status:beats?.length?'playing':'complete',revision:0};}
export function advancePerformance(run,dt){if(run.status!=='playing'||!Number.isFinite(dt)||dt<0)return run;run.elapsed+=Math.min(dt,.25);let guard=0;while(run.status==='playing'&&run.elapsed>=Math.max(.2,run.beats[run.index].duration||2.5)&&guard++<8){run.elapsed-=Math.max(.2,run.beats[run.index].duration||2.5);run.index++;run.revision++;if(run.index===run.beats.length){run.status='complete';run.elapsed=0;}}return run;}
export function cancelPerformance(run){if(run.status==='playing'){run.status='cancelled';run.revision++;}return run;}
export function samplePerformance(beat,elapsed=0){if(!beat)return null;return {speaker:beat.speaker,listener:beat.lookAt||'player',gesture:beat.gesture||'rest',gaze:beat.lookAt||'player',camera:beat.camera||'two-shot',prop:beat.prop||null,cue:beat.cue||null,line:beat.line||'',progress:Math.min(1,Math.max(0,elapsed/Math.max(.2,beat.duration||2.5)))};}
export const beat=(speaker,line,gesture='rest',extra={})=>({speaker,line,gesture,action:gesture,duration:Math.max(1.8,Math.min(5.5,line.split(/\s+/).length*.22+.65)),...extra});
